-- corpus/sqlite/schema.sql with data generators that both SQLite and DuckDB accept (no hex, datetime,
-- date, char, json_object): the setup for cross-engine probing (C4) between SQLite-dialect engines and DuckDB.
CREATE TABLE t0 (c0 INTEGER, c1 TEXT, c2 REAL);
CREATE TABLE t1 (c0 INTEGER PRIMARY KEY, c1 INTEGER, c2 TEXT);
CREATE TABLE t2 (c0 BIGINT, c1 NUMERIC CHECK (c1 >= 0), c2 TEXT DEFAULT '2024-06-01 00:00:00');
CREATE TABLE t3 (c0 INTEGER NOT NULL, c1 BOOLEAN, c2 DATE, c5 TEXT);
CREATE TABLE t4 (c0 INTEGER, c1 INTEGER GENERATED ALWAYS AS (c0 * 2) VIRTUAL, c3 NUMERIC);
CREATE TABLE tp (c0 INTEGER NOT NULL, c1 TEXT);
CREATE TABLE tl (c0 INTEGER, c1 TEXT);
CREATE TABLE ti (c0 INTEGER, c1 TEXT);
INSERT INTO t0 SELECT g % 17, 'v' || (g * 7 % 13), g / 3.0 FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 200) SELECT g FROM s);
INSERT INTO t0 VALUES (NULL, NULL, NULL), (0, '', 0.0), (-1, 'x', -1.5);
INSERT INTO t1 SELECT g, NULLIF(g - 1, 0), '{"k": ' || g || ', "a": [' || g || ', ' || (g * 2) || ']}' FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 50) SELECT g FROM s);
INSERT INTO t2 SELECT g, g * 1.5, '2024-01-' || (10 + g % 20) || ' 0' || (g % 10) || ':00:00' FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 30) SELECT g FROM s);
INSERT INTO t3 SELECT g % 23, CASE WHEN g % 5 = 0 THEN NULL ELSE g % 2 = 0 END, '2024-02-' || (10 + g % 18), CASE g % 3 WHEN 0 THEN 'A' WHEN 1 THEN 'B' ELSE 'C' END FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 100) SELECT g FROM s);
INSERT INTO t4 (c0, c3) SELECT CASE WHEN g % 9 = 0 THEN NULL ELSE g % 31 END, g / 7.0 FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 120) SELECT g FROM s);
INSERT INTO tp SELECT g, CAST(g AS TEXT) FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 200) SELECT g FROM s);
INSERT INTO tl SELECT g, CASE g % 4 WHEN 0 THEN 'a' WHEN 1 THEN 'b' WHEN 2 THEN 'c' END FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 80) SELECT g FROM s);
INSERT INTO ti SELECT g, CAST(g AS TEXT) FROM (WITH RECURSIVE s(g) AS (SELECT 1 UNION ALL SELECT g + 1 FROM s WHERE g < 40) SELECT g FROM s);
CREATE VIEW v0 AS SELECT c0, count(*) AS n FROM t0 GROUP BY c0;
CREATE INDEX i0 ON t0 (c0);
CREATE INDEX i4 ON t3 (c0, c2);
ANALYZE;
